// npm install --prefix artifacts/mcp-meta-build --ignore-scripts ajv@8.17.1
// node tests/JarvisCode.Parity.Tests/Captures/Mcp/gen-schema-meta.cjs artifacts/mcp-meta-build/node_modules
// Runtime output is standalone trusted code; schemas are data, never compiled code.
const fs = require('node:fs');
const path = require('node:path');
const packages = path.resolve(process.argv[2]);
const root = path.resolve(__dirname, '../../../..');
const Ajv = require(path.join(packages, 'ajv/dist/2020')).default;
const standalone = require(path.join(packages, 'ajv/dist/standalone')).default;
if (require(path.join(packages, 'ajv/package.json')).version !== '8.17.1') throw Error('Expected Ajv 8.17.1');
const ajv = new Ajv({allErrors:false, validateFormats:false, code:{source:true}});
const validate = ajv.getSchema('https://json-schema.org/draft/2020-12/schema');
const equal = require(path.join(packages, 'fast-deep-equal'));
const code = `// Generated by gen-schema-meta.cjs from Ajv 8.17.1 and its draft 2020-12 meta-schema.\n` +
  `// MIT licenses are shipped in ThirdParty/Ajv. Do not hand-edit.\n` +
  `var module={exports:{}};var __equal=${equal.toString()};\n` +
  `function require(id){if(id==='ajv/dist/runtime/equal')return {default:__equal};throw new Error('Unexpected validator dependency: '+id);}\n` +
  standalone(ajv, validate) + '\n' +
  `function validateMcpSchemaJson(json){var data=JSON.parse(json);var valid=module.exports(data);var error=module.exports.errors&&module.exports.errors[0];return JSON.stringify({valid:valid,detail:valid?null:error?'schema'+error.instancePath+' '+(error.message||'is invalid'):'schema is invalid'});}\n`;
fs.writeFileSync(path.join(root,'src/JarvisCode.Core/Mcp/SchemaMetaValidator.js'), code);
const licenses = path.join(root,'src/JarvisCode.Core/ThirdParty/Ajv');
fs.mkdirSync(licenses,{recursive:true});
fs.copyFileSync(path.join(packages,'ajv/LICENSE'),path.join(licenses,'Ajv-LICENSE.txt'));
fs.copyFileSync(path.join(packages,'fast-deep-equal/LICENSE'),path.join(licenses,'fast-deep-equal-LICENSE.txt'));
fs.writeFileSync(path.join(licenses,'VERSION.txt'),'Ajv 8.17.1; fast-deep-equal '+require(path.join(packages,'fast-deep-equal/package.json')).version+'\nhttps://ajv.js.org/standalone.html\n');
console.log('Wrote '+code.length+' bytes');
